arguments.content:
/* TodoMVC vanilla JS implementation.
 *
 * Reads and writes todos to localStorage under `todos-vanilla`, one record per item with
 * the shape { id, title, completed }. Editing state is never persisted. Routing is hash
 * based (#/, #/active, #/completed); the active route is persisted under `todos-vanilla-route`
 * so it survives a reload.
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ROUTE_KEY = 'todos-vanilla-route';

  var w = window;
  var doc = document;

  var newTodoInput = doc.querySelector('.new-todo');
  var main = doc.getElementById('main');
  var footer = doc.getElementById('footer');
  var list = doc.querySelector('.todo-list');
  var toggleAll = doc.getElementById('toggle-all');
  var clearCompleted = doc.querySelector('.clear-completed');
  var count = doc.querySelector('.todo-count');
  var filters = doc.querySelector('.filters');

  /** @planks("the localStorage key {string} contains a record with title {string}") */
  /** @planks("the todo {string} is stored as active") */
  /** @planks("the todo {string} is stored as completed") */
  /** @planks("the localStorage key {string} holds an array whose items conform to the {string} schema in {string}") */
  function load() {
    var raw = w.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function save(todos) {
    w.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId(todos) {
    var max = 0;
    for (var i = 0; i < todos.length; i++) {
      var id = todos[i].id;
      if (typeof id === 'number' && id > max) max = id;
    }
    return max + 1;
  }

  function getRoute() {
    var r = w.location.hash;
    if (!r || r === '#') r = w.localStorage.getItem(ROUTE_KEY) || '#/';
    return r;
  }

  function setRoute(r) {
    w.localStorage.setItem(ROUTE_KEY, r);
  }

  /** @planks("the {string} section is hidden") */
  /** @planks("the todo {string} is present in the list") */
  /** @planks("the todo-count shows {string}") */
  /** @planks("the todo {string} has the {string} class") */
  /** @planks("the todo {string} does not have the {string} class") */
  /** @planks("the toggle-all checkbox is checked") */
  /** @planks("the toggle-all checkbox is unchecked") */
  /** @planks("every todo item has a {string} button") */
  /** @planks("the clear-completed button is hidden") */
  /** @planks("the {string} filter link has the {string} class") */
  /** @planks("the todo {string} is visible") */
  /** @planks("the todo {string} is hidden") */
  /** @planks("the new-todo input is empty") */
  /** @planks("no todo item is present in the list") */
  function render() {
    var todos = load();
    var route = getRoute();

    list.innerHTML = '';
    todos.forEach(function (t) {
      var li = doc.createElement('li');
      if (t.completed) li.className = 'completed';

      var view = doc.createElement('div');
      view.className = 'view';
      var toggle = doc.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = t.completed;
      var label = doc.createElement('label');
      label.textContent = t.title;
      var destroy = doc.createElement('button');
      destroy.className = 'destroy';
      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = doc.createElement('input');
      edit.className = 'edit';
      edit.value = t.title;

      li.appendChild(view);
      li.appendChild(edit);

      var hidden =
        (route === '#/active' && t.completed) ||
        (route === '#/completed' && !t.completed);
      if (hidden) li.hidden = true;

      list.appendChild(li);
    });

    var hasTodos = todos.length > 0;
    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    var allCompleted = hasTodos && todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;

    var active = todos.filter(function (t) { return !t.completed; }).length;
    var word = active === 1 ? 'item' : 'items';
    count.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';

    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompleted.hidden = !hasCompleted;

    var links = filters.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      var href = links[i].getAttribute('href');
      if (
        (route === '#/' && href === '#/') ||
        (route === '#/active' && href === '#/active') ||
        (route === '#/completed' && href === '#/completed')
      ) {
        links[i].classList.add('selected');
      } else {
        links[i].classList.remove('selected');
      }
    }
  }

  /** @planks("the new-todo input is focused") */
  function init() {
    newTodoInput.focus();
    render();
  }

  /** @planks("the user adds the todo {string}") */
  /** @planks("the user enters {string} in the new-todo input and presses Enter") */
  function handleNewTodo(e) {
    if (e.key !== 'Enter') return;
    var value = newTodoInput.value.trim();
    if (value) {
      var todos = load();
      todos.push({ id: nextId(todos), title: value, completed: false });
      save(todos);
    }
    newTodoInput.value = '';
    render();
  }

  /** @planks("the user clicks the checkbox of {string}") */
  function handleToggle(e) {
    var toggle = e.target.closest ? e.target.closest('.toggle') : null;
    if (!toggle) return;
    var li = toggle.closest('li');
    var title = li.querySelector('label').textContent;
    var todos = load();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].completed = toggle.checked;
        break;
      }
    }
    save(todos);
    render();
  }

  /** @planks("the user clicks the toggle-all checkbox") */
  function handleToggleAll() {
    var todos = load();
    for (var i = 0; i < todos.length; i++) todos[i].completed = toggleAll.checked;
    save(todos);
    render();
  }

  /** @planks("the user double-clicks the label of {string}") */
  /** @planks("the edit input of {string} is focused") */
  function handleDblClick(e) {
    var label = e.target.closest ? e.target.closest('label') : null;
    if (!label) return;
    var li = label.closest('li');
    li.classList.add('editing');
    li.querySelector('.edit').focus();
  }

  /** @planks("the user edits the label of {string} to {string} and presses Enter") */
  /** @planks("the user edits the label of {string} to {string} and blurs") */
  /** @planks("the user edits the label of {string} to {string} and presses Escape") */
  /** @planks("the user clears the edit input of {string} and presses Enter") */
  /** @planks("the todo {string} is not in editing mode") */
  function commitEdit(li, raw) {
    var title = li.querySelector('label').textContent;
    var value = raw.trim();
    var todos = load();
    if (value === '') {
      var remaining = todos.filter(function (t) { return t.title !== title; });
      save(remaining);
      render();
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].title = value;
        break;
      }
    }
    save(todos);
    render();
  }

  function handleEditKeydown(e) {
    var edit = e.target.closest ? e.target.closest('.edit') : null;
    if (!edit) return;
    var li = edit.closest('li');
    if (e.key === 'Enter') {
      commitEdit(li, edit.value);
    } else if (e.key === 'Escape') {
      li.classList.remove('editing');
      render();
    }
  }

  function handleEditBlur(e) {
    var edit = e.target.closest ? e.target.closest('.edit') : null;
    if (!edit) return;
    var li = edit.closest('li');
    if (li.classList.contains('editing')) commitEdit(li, edit.value);
  }

  /** @planks("the user clicks the clear-completed button") */
  function handleClearCompleted() {
    var todos = load();
    var remaining = todos.filter(function (t) { return !t.completed; });
    save(remaining);
    render();
  }

  /** @planks("the user navigates to {string}") */
  function handleHashChange() {
    setRoute(w.location.hash);
    render();
  }

  newTodoInput.addEventListener('keydown', handleNewTodo);
  list.addEventListener('change', handleToggle);
  list.addEventListener('click', function (e) {
    var destroy = e.target.closest ? e.target.closest('.destroy') : null;
    if (!destroy) return;
    var li = destroy.closest('li');
    var title = li.querySelector('label').textContent;
    var todos = load();
    save(todos.filter(function (t) { return t.title !== title; }));
    render();
  });
  list.addEventListener('dblclick', handleDblClick);
  list.addEventListener('keydown', handleEditKeydown);
  list.addEventListener('blur', handleEditBlur, true);
  toggleAll.addEventListener('change', handleToggleAll);
  clearCompleted.addEventListener('click', handleClearCompleted);
  w.addEventListener('hashchange', handleHashChange);

  init();
})();

