const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');

function readStore(world, key) {
  const raw = world.localStorage.getItem(key);
  assert(raw, 'localStorage key ' + key + ' missing');
  return JSON.parse(raw);
}

function nextId(todos) {
  let max = 0;
  for (const t of todos) {
    if (typeof t.id === 'number' && t.id > max) max = t.id;
  }
  return max + 1;
}

function seedTodo(world, title, completed) {
  const todos = world.localStorage.getItem('todos-vanilla');
  const list = todos ? JSON.parse(todos) : [];
  if (!list.some((t) => t.title === title)) {
    list.push({ id: nextId(list), title, completed });
    world.localStorage.setItem('todos-vanilla', JSON.stringify(list));
  }
  // Re-render from the seeded store: dispatch hashchange, which the app handles by rendering.
  world.window.dispatchEvent(new world.window.Event('hashchange'));
}

function findItem(world, title) {
  const items = world.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  return null;
}

Given('the app has loaded', function () {});

Then('the {string} section is hidden', function (sel) {
  const el = this.document.querySelector(sel);
  assert(el, 'element ' + sel + ' not found');
  assert.strictEqual(el.hidden, true, sel + ' should be hidden');
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input, 'new-todo input should be focused');
});

When('the user adds the todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter' }));
});

Then('the todo {string} is present in the list', function (title) {
  assert(findItem(this, title), 'todo ' + title + ' not present in the list');
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be empty');
});

When('the user enters {string} in the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter' }));
});

Then('no todo item is present in the list', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'expected no todo items, found ' + items.length);
});

Given('the todo {string} is active', function (title) {
  seedTodo(this, title, false);
});

Given('the todo {string} is completed', function (title) {
  seedTodo(this, title, true);
});

When('the user clicks the toggle-all checkbox', function () {
  const ta = this.document.getElementById('toggle-all');
  ta.checked = !ta.checked;
  ta.dispatchEvent(new this.window.Event('change'));
});

Then('the todo {string} has the {string} class', function (title, cls) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(li.classList.contains(cls), 'todo ' + title + ' missing class ' + cls);
});

Then('the todo {string} does not have the {string} class', function (title, cls) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(!li.classList.contains(cls), 'todo ' + title + ' should not have class ' + cls);
});

Then('the toggle-all checkbox is checked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.strictEqual(ta.checked, true, 'toggle-all should be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.strictEqual(ta.checked, false, 'toggle-all should be unchecked');
});

When('the user clicks the checkbox of {string}', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const cb = li.querySelector('.toggle');
  cb.checked = !cb.checked;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user double-clicks the label of {string}', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the todo {string} is in editing mode', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(li.classList.contains('editing'), 'todo ' + title + ' should be in editing mode');
});

Then('the edit input of {string} is focused', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  assert.strictEqual(this.document.activeElement, edit, 'edit input of ' + title + ' should be focused');
});

When('the user edits the label of {string} to {string} and presses Enter', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter' }));
});

Then('the todo {string} is not present in the list', function (title) {
  assert(!findItem(this, title), 'todo ' + title + ' should not be present');
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert(!li.classList.contains('editing'), 'todo ' + title + ' should not be in editing mode');
});

When('the user edits the label of {string} to {string} and blurs', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.Event('blur'));
});

When('the user clears the edit input of {string} and presses Enter', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = '';
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter' }));
});

When('the user edits the label of {string} to {string} and presses Escape', function (title, newTitle) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape' }));
});

Then('every todo item has a {string} button', function (cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert(items.length > 0, 'expected at least one todo item');
  for (const li of items) {
    assert(li.querySelector('button.' + cls), 'todo item missing ' + cls + ' button');
  }
});

Then('the todo-count shows {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  assert.strictEqual(count.textContent, text, 'todo-count should show "' + text + '" but showed "' + count.textContent + '"');
});

When('the user clicks the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(btn.hidden, true, 'clear-completed button should be hidden');
});

Then('the localStorage key {string} contains a record with title {string}', function (key, title) {
  const data = readStore(this, key);
  assert(Array.isArray(data) && data.some((t) => t.title === title), 'no record with title ' + title);
});

Then('the todo {string} is stored as active', function (title) {
  const data = readStore(this, 'todos-vanilla');
  const t = data.find((x) => x.title === title);
  assert(t, 'no stored record for ' + title);
  assert.strictEqual(t.completed, false, title + ' should be stored as active');
});

Then('the todo {string} is stored as completed', function (title) {
  const data = readStore(this, 'todos-vanilla');
  const t = data.find((x) => x.title === title);
  assert(t, 'no stored record for ' + title);
  assert.strictEqual(t.completed, true, title + ' should be stored as completed');
});

When('the page is reloaded', async function () {
  const seed = {};
  const ls = this.localStorage;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    seed[k] = ls.getItem(k);
  }
  await this.disposeApp();
  this.loadApp(seed);
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

Then('the todo {string} is visible', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' not found');
  assert.strictEqual(li.hidden, false, 'todo ' + title + ' should be visible');
});

Then('the todo {string} is hidden', function (title) {
  const li = findItem(this, title);
  assert(li, 'todo ' + title + ' should exist to be hidden');
  assert.strictEqual(li.hidden, true, 'todo ' + title + ' should be hidden');
});

Then('the {string} filter link has the {string} class', function (name, cls) {
  const links = this.document.querySelectorAll('.filters a');
  let found = null;
  for (const a of links) {
    if (a.textContent.trim() === name) found = a;
  }
  assert(found, 'filter link ' + name + ' not found');
  assert(found.classList.contains(cls), 'filter link ' + name + ' should have class ' + cls);
});

Then(
  'the localStorage key {string} holds an array whose items conform to the {string} schema in {string}',
  function (key, schemaName, schemaPath) {
    const data = readStore(this, key);
    const schema = JSON.parse(fs.readFileSync(path.resolve(ROOT, schemaPath), 'utf8'));
    validateTodoRecord(data, schema);
  }
);

function validateTodoRecord(data, schema) {
  const name = schema.title || 'schema';
  assert(Array.isArray(data), name + ': expected an array');

  const itemSchema = schema.items;
  const required = itemSchema.required || [];
  const props = itemSchema.properties || {};

  data.forEach((item, i) => {
    assert(item && typeof item === 'object' && !Array.isArray(item), name + ': item ' + i + ' is not an object');

    required.forEach((k) => {
      assert(k in item, name + ': item ' + i + ' missing required property "' + k + '"');
    });

    const idTypes = Array.isArray(itemSchema.properties.id.type)
      ? itemSchema.properties.id.type
      : [itemSchema.properties.id.type];
    assert(
      idTypes.some((t) => typeof item.id === t),
      name + ': item ' + i + ' id has wrong type'
    );
    assert.strictEqual(typeof item.title, props.title.type, name + ': item ' + i + ' title has wrong type');
    assert.strictEqual(
      typeof item.completed,
      props.completed.type,
      name + ': item ' + i + ' completed has wrong type'
    );

    Object.keys(item).forEach((k) => {
      assert(k in props, name + ': item ' + i + ' has unexpected property "' + k + '"');
    });
  });
}

